<?php $page_title='Admin Users';require 'includes/header.php';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$a=$_POST['action'];$id=(int)($_POST['id']??0);if($a==='save'){if($id)$pdo->prepare("UPDATE users SET name=?,email=? WHERE id=? AND role='admin'")->execute([trim($_POST['name']),trim($_POST['email']),$id]);else$pdo->prepare("INSERT INTO users(name,email,password,role) VALUES(?,?,?,'admin')")->execute([trim($_POST['name']),trim($_POST['email']),password_hash($_POST['password'],PASSWORD_DEFAULT)]);flash('success','Admin saved.');}elseif($a==='password'){$pdo->prepare("UPDATE users SET password=? WHERE id=? AND role='admin'")->execute([password_hash($_POST['password'],PASSWORD_DEFAULT),$id]);flash('success','Admin password changed.');}elseif($a==='delete'){$me=(int)$_SESSION['user_id'];if($id===$me)flash('error','Your current admin account cannot be deleted.');else{$pdo->prepare("DELETE FROM users WHERE id=? AND role='admin'")->execute([$id]);flash('success','Admin removed.');}}header('Location: admins.php');exit;}$admins=$pdo->query("SELECT * FROM users WHERE role='admin' ORDER BY created_at")->fetchAll();?>
<div class="page-head"><div><h1>Admin Users</h1><p>Role-based admin access. Customer accounts cannot enter /admin/.</p></div></div><div class="panel" style="margin-bottom:18px"><h2>Add admin</h2><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="save"><div class="form-grid"><input class="input" name="name" placeholder="Admin name" required><input class="input" type="email" name="email" placeholder="Email" required><input class="input" type="password" name="password" placeholder="Password (8+ chars)" minlength="8" required></div><br><button class="btn">Add admin</button></form></div><div class="panel"><div class="table-wrap"><table><tr><th>Name</th><th>Email</th><th>Created</th><th>Actions</th></tr><?php foreach($admins as $a):?><tr><td><?=e($a['name'])?></td><td><?=e($a['email'])?></td><td><?=date('M d, Y',strtotime($a['created_at']))?></td><td><form method="post" style="display:inline"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="password"><input type="hidden" name="id" value="<?=$a['id']?>"><input class="input" style="width:150px;display:inline" type="password" name="password" placeholder="New password" required><button class="btn light">Change</button></form> <form method="post" style="display:inline"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$a['id']?>"><button class="btn danger" data-confirm="Remove this admin?">Remove</button></form></td></tr><?php endforeach;?></table></div></div><?php require 'includes/footer.php';?>
